<?php
require_once __DIR__.'/../includes/functions.php';admin_required();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$estado=$_POST['estado']??'';$pago=isset($_POST['pago_confirmado'])?1:0;$allowed=['pendiente','confirmado','preparando','en_camino','listo_recojo','entregado','cancelado'];
 if(!in_array($estado,$allowed,true))$error='Estado no válido.';
 else {try{$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM pedidos WHERE id=? FOR UPDATE');$s->execute([$id]);$order=$s->fetch();if(!$order)throw new RuntimeException('Pedido no encontrado.');
  if($estado==='cancelado'&&(int)$order['stock_descontado']===1)throw new RuntimeException('Este pedido ya descontó stock. No lo canceles desde aquí; gestiona una devolución manual del inventario.');
  if($pago===1 && (int)$order['stock_descontado']===0 && $estado!=='cancelado'){
   $d=$pdo->prepare('SELECT producto_id,cantidad,nombre_producto FROM pedido_detalles WHERE pedido_id=?');$d->execute([$id]);
   foreach($d->fetchAll() as $line){if($line['producto_id']===null)continue;$st=$pdo->prepare('SELECT stock FROM productos WHERE id=? FOR UPDATE');$st->execute([$line['producto_id']]);$prod=$st->fetch();if(!$prod||(int)$prod['stock']<(int)$line['cantidad'])throw new RuntimeException('Stock insuficiente para confirmar el pago de '.$line['nombre_producto']);$up=$pdo->prepare('UPDATE productos SET stock=stock-? WHERE id=?');$up->execute([$line['cantidad'],$line['producto_id']]);}
   $v=$pdo->prepare('INSERT INTO ventas(pedido_id,subtotal,costo_delivery,total,metodo_pago) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE pedido_id=VALUES(pedido_id)');$v->execute([$id,$order['subtotal'],$order['costo_delivery'],$order['total'],$order['metodo_pago']]);
   $upd=$pdo->prepare('UPDATE pedidos SET stock_descontado=1,pago_confirmado=1,estado=? WHERE id=?');$upd->execute([$estado,$id]);
  } else {$upd=$pdo->prepare('UPDATE pedidos SET pago_confirmado=?,estado=? WHERE id=?');$upd->execute([$pago,$estado,$id]);}
  $pdo->commit();set_flash('Pedido actualizado. '.($pago?'Pago confirmado y venta registrada si correspondía.':''));redirect('admin/pedidos.php?id='.$id);
 }catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();$error=$ex instanceof RuntimeException?$ex->getMessage():'No se pudo actualizar el pedido.';}}
}
$selected=(int)($_GET['id']??0);$list=db()->query('SELECT * FROM pedidos ORDER BY id DESC LIMIT 100')->fetchAll();$detail=null;$lines=[];
if($selected){$s=db()->prepare('SELECT * FROM pedidos WHERE id=?');$s->execute([$selected]);$detail=$s->fetch();if($detail){$s=db()->prepare('SELECT * FROM pedido_detalles WHERE pedido_id=?');$s->execute([$selected]);$lines=$s->fetchAll();}}
$pageTitle='Pedidos y ventas';require __DIR__.'/../includes/header.php';
?>
<div class="section-head"><div><div class="eyebrow">Administración</div><h1>Pedidos y ventas</h1><p class="muted">Revisa pedidos y confirma pagos solo cuando estén verificados.</p></div><a class="btn secondary" href="<?= e(url('admin/index.php')) ?>">← Panel</a></div>
<?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?>
<?php if($detail): ?><section class="panel" style="margin-bottom:24px"><h2>Pedido <?= e($detail['codigo']) ?></h2><div class="grid-two"><div><p><strong>Cliente:</strong> <?= e($detail['cliente_nombre']) ?></p><p><strong>Teléfono:</strong> <?= e($detail['cliente_telefono']) ?></p><p><strong>Correo:</strong> <?= e($detail['cliente_email']??'—') ?></p><p><strong>Entrega:</strong> <?= e($detail['tipo_entrega']==='delivery'?'Delivery':'Recojo') ?></p><p><strong>Dirección:</strong> <?= e($detail['direccion']??'No aplica') ?></p><p><strong>Pago:</strong> <?= e($detail['metodo_pago']) ?></p><p><strong>Notas:</strong> <?= e($detail['notas']??'—') ?></p><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Total</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= e($l['nombre_producto']) ?></td><td><?= (int)$l['cantidad'] ?></td><td><?= money($l['total_linea']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="total">Total: <?= money($detail['total']) ?></p></div><div><form class="form-card" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$detail['id'] ?>"><label>Estado del pedido</label><select name="estado"><?php foreach(['pendiente','confirmado','preparando','en_camino','listo_recojo','entregado','cancelado'] as $state): ?><option value="<?= e($state) ?>" <?= $detail['estado']===$state?'selected':'' ?>><?= e($state) ?></option><?php endforeach; ?></select><label style="display:flex;gap:10px;align-items:center"><input style="width:auto" type="checkbox" name="pago_confirmado" value="1" <?= (int)$detail['pago_confirmado']?'checked':'' ?> <?= (int)$detail['stock_descontado']?'disabled':'' ?>> Pago verificado / confirmar venta</label><?php if((int)$detail['stock_descontado']): ?><p class="muted">La venta ya fue registrada y el stock descontado.</p><?php else: ?><p class="muted">Al marcar pago verificado, se comprobará el stock, se descontará una sola vez y se registrará la venta.</p><?php endif; ?><button style="width:100%">Guardar cambios</button></form></div></div></section><?php elseif($selected): ?><div class="alert error">No se encontró el pedido solicitado.</div><?php endif; ?>
<section class="panel"><h2>Todos los pedidos recientes</h2><div class="table-wrap"><table><thead><tr><th>Código</th><th>Cliente</th><th>Entrega</th><th>Total</th><th>Estado</th><th>Pago</th><th>Fecha</th></tr></thead><tbody><?php foreach($list as $o): ?><tr><td><a href="<?= e(url('admin/pedidos.php?id='.(int)$o['id'])) ?>"><strong><?= e($o['codigo']) ?></strong></a></td><td><?= e($o['cliente_nombre']) ?></td><td><?= e($o['tipo_entrega']) ?></td><td><?= money($o['total']) ?></td><td><?= e($o['estado']) ?></td><td><?= (int)$o['pago_confirmado']?'Confirmado':'Pendiente' ?></td><td><?= e($o['creado_en']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
